import{z as i,x as n,o as B,c as p,q as l,j as o,D as e,d as t,s as A,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"灰度光刻","description":"","frontmatter":{"title":"灰度光刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/grayscale-litho.md","filePath":"litho/grayscale-litho.md","lastUpdated":1791413859000}'),d={name:"litho/grayscale-litho.md"};function h(D,E,F,m,C,c){const r=n("Mermaid");return B(),p("div",null,[E[2]||(E[2]=l('<h1 id="灰度光刻" tabindex="-1">灰度光刻 <a class="header-anchor" href="#灰度光刻" aria-label="Permalink to &quot;灰度光刻&quot;">​</a></h1><div class="epigraph"><p>二元掩模只印「有/无」；灰度把局部剂量映射成胶的剩余厚度，一次曝光做出斜面和微透镜。</p><footer>—— 对照 grayscale lithography 与剂量调制三维胶轮廓的通称</footer></div><p><a href="/litho/mems-patterning">上一课</a>需要三维结构。缺口是如何不用许多层二元曝光去堆斜面。本课钉灰度光刻。双光子把三维做到体素，留给<a href="/litho/two-photon-3d">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>灰度：掩模透过率连续或分多档，或激光直写调功率，使胶在显影后高度随剂量变。用于微透镜阵列、DOE、MEMS 斜面。校准是胶的对比度曲线（γ）与显影，薄膜驻波会调制高度——轨道与薄膜课的物理在此变成高度噪声。</p><p><span class="marginnote">术语翻译：胶的 γ（对比度）是「剂量差 → 溶解速率差」的放大倍数。γ 高，剂量刚过阈就全溶或全不溶，边缘锐利，适合 IC；γ 低，剂量渐变时厚度也跟着渐变，正好当「剂量→高度」的斜坡，适合灰度。一支胶很难两头讨好。</span></p><p>缺口是<strong>剂量→高度</strong>，不是平面 CD。把灰度当 OPC 的剂量 MPC，对象错了：这里高度是产品。</p><h3 id="与-vsb-灰度炮的区别" tabindex="-1">与 VSB 灰度炮的区别 <a class="header-anchor" href="#与-vsb-灰度炮的区别" aria-label="Permalink to &quot;与 VSB 灰度炮的区别&quot;">​</a></h3><p>掩模写入灰度是为了斜边逼近；本课是晶圆/器件灰度。同词不同层。</p><p><span class="marginnote">低 γ 胶对灰度友好（高度渐变），对 IC 锐边不友好。胶不能两头讨好。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：透过率图或激光位图。校准：台阶高度计或光学轮廓。工艺：厚胶、软烘、显影终点。转印：有时再回流（resist reflow 课）把台阶熔成光滑透镜。</p><p><span class="marginnote">直觉类比：灰度掩模之于二元掩模，就像灰阶照片之于黑白剪影——剪影只有「有墨/无墨」两档，印不出人脸的立体感；灰阶连明暗起伏一起记录。胶把「墨色深浅」翻译成「剩余厚度」，于是平面工艺一次曝光就能长出透镜的弧面。</span></p>',13)),(B(),o(s,null,{default:e(()=>[A(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DES%5B%22%E8%AE%BE%E8%AE%A1%EF%BC%9A%E9%80%8F%E8%BF%87%E7%8E%87%E5%9B%BE%20%2F%20%E6%BF%80%E5%85%89%E4%BD%8D%E5%9B%BE%22%5D%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%EF%BC%9A%E5%89%82%E9%87%8F%E6%8C%89%E5%9B%BE%E5%88%86%E5%B8%83%22%5D%0A%20%20EXP%20--%3E%20DEV%5B%22%E6%98%BE%E5%BD%B1%EF%BC%9A%E5%89%A9%E4%BD%99%E5%8E%9A%E5%BA%A6%E9%9A%8F%E5%89%82%E9%87%8F%22%5D%0A%20%20DEV%20--%3E%20MEAS%5B%22%E6%B5%8B%E9%87%8F%EF%BC%9A%E5%8F%B0%E9%98%B6%E9%AB%98%E5%BA%A6%E8%AE%A1%20%2F%20%E5%85%89%E5%AD%A6%E8%BD%AE%E5%BB%93%22%5D%0A%20%20MEAS%20--%3E%20CAL%7B%22%E9%AB%98%E5%BA%A6%E8%B4%B4%E5%90%88%E7%9B%AE%E6%A0%87%E8%BD%AE%E5%BB%93%EF%BC%9F%22%7D%0A%20%20CAL%20--%20%22%E5%90%A6%22%20--%3E%20TUNE%5B%22%E8%B0%83%20%CE%B3%20%E6%A0%A1%E5%87%86%E6%9B%B2%E7%BA%BF%20%2F%20%E7%83%98%E7%83%A4%20%2F%20%E6%98%BE%E5%BD%B1%E6%97%B6%E9%97%B4%22%5D%0A%20%20TUNE%20--%3E%20EXP%0A%20%20CAL%20--%20%22%E6%98%AF%22%20--%3E%20REFL%7B%22%E9%9C%80%E8%A6%81%E6%9B%B4%E5%85%89%E6%BB%91%E7%9A%84%E5%BC%A7%E9%9D%A2%EF%BC%9F%22%7D%0A%20%20REFL%20--%20%22%E6%98%AF%22%20--%3E%20RF%5B%22%E5%9B%9E%E6%B5%81%EF%BC%9A%E6%8A%8A%E5%8F%B0%E9%98%B6%E7%86%94%E6%88%90%E8%BF%9E%E7%BB%AD%E9%80%8F%E9%95%9C%22%5D%0A%20%20REFL%20--%20%22%E5%90%A6%22%20--%3E%20DONE%5B%22%E6%88%90%E5%93%81%EF%BC%9A%E5%BE%AE%E9%80%8F%E9%95%9C%20%2F%20MEMS%20%E6%96%9C%E9%9D%A2%22%5D%0A%20%20RF%20--%3E%20DONE%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"剩余厚度是溶解速率对剂量积分的结果。驻波给出 z 方向条纹，灰度表面变「波纹」。抗反射与烘烤与 IC 相同物理，规格源换成表面 rms。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：193 nm 光在折射率约 1.7 的胶里，驻波条纹间隔约 \\(\\lambda/(2n)\\approx 57\\) nm。灰度表面本该是几微米级的光滑弧面，若底部反光没压住，弧面上就叠了一层几十纳米周期的「洗衣板」，直接进表面 rms 报废项。")],-1)),(B(),o(s,null,{default:e(()=>[A(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%80%8F%E8%BF%87%E7%8E%87%20%2F%20%E6%BF%80%E5%85%89%E5%8A%9F%E7%8E%87%22%5D%20--%3E%20D%5B%22%E5%B1%80%E9%83%A8%E5%89%82%E9%87%8F%22%5D%0A%20%20D%20--%3E%20Z%5B%22%E5%89%A9%E4%BD%99%E8%83%B6%E5%8E%9A%22%5D%0A%20%20SW%5B%22%E9%A9%BB%E6%B3%A2%22%5D%20--%3E%20RIP%5B%22%E9%AB%98%E5%BA%A6%E6%B3%A2%E7%BA%B9%22%5D%0A%20%20Z%20--%3E%20DEV%5B%22%E5%BE%AE%E9%80%8F%E9%95%9C%20%2F%20%E6%96%9C%E9%9D%A2%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>灰度不服务 MMP 逻辑。动态范围受胶 γ 与掩模档数限制。不把 3D IC 的多层金属当灰度。</p><p>后课默认：二维剂量可映射高度；下一课非线性双光子把曝光关在焦点体素里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>灰度光刻把剂量写成胶高度，服务微光学与 MEMS 斜面。</li><li>胶 γ 与驻波决定高度精度。</li><li>与掩模写入灰度同词不同对象。</li><li>出处：grayscale lithography 通称。</li></ul>',5))])}const _=i(d,[["render",h]]);export{u as __pageData,_ as default};
